package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type OrderRec struct {
	OrId    string
	OrStat  string
	OrQty   int64
	OrPrice decimal.Decimal
}

var WsEofFlag string = "N"
var WsTotal decimal.Decimal = decimal.NewFromInt(0)
var WsGrand decimal.Decimal = decimal.NewFromInt(0)
var WsNewCount int64 = 0
var WsShipCount int64 = 0
var WsCancelCount int64 = 0
var WsInvalid int64 = 0
var WsBadQty int64 = 0
var WsQtyEd string
var WsPriceEd string
var WsTotalEd string
var WsGrandEd string

var OrderRecVar OrderRec

var orderFile *os.File
var orderReader *bufio.Scanner
var inputDone bool

func formatEdited(val decimal.Decimal, pic string) string {
	// Determine scale: count of 9 after '.'
	scale := 0
	dotIdx := strings.Index(pic, ".")
	if dotIdx >= 0 {
		for i := dotIdx + 1; i < len(pic); i++ {
			c := pic[i]
			if c == '9' || c == 'Z' {
				scale++
			}
		}
	}
	// integer picture chars: count of 9/Z and commas before dot
	intPic := pic
	if dotIdx >= 0 {
		intPic = pic[:dotIdx]
	}
	intSlots := 0
	for _, ch := range intPic {
		if ch == '9' || ch == 'Z' || ch == ',' {
			intSlots++
			_ = intSlots
		}
	}
	// Actually width is len(pic)
	width := len(pic)

	// Prepare absolute value string with scale decimals, truncating/padding
	// For MOVE formatting, value is already truncated to correct scale, but we need to handle
	// We truncate toward zero to scale for safety, but if value has more decimals, we need to truncate
	// Use Truncate
	v := val.Truncate(int64(scale))
	// Get string with exactly scale decimal places
	// Use StringFixed
	s := v.StringFixed(int32(scale)) // may include minus sign
	negative := false
	if strings.HasPrefix(s, "-") {
		negative = true
		s = s[1:]
	}
	// Split integer and fractional
	var intPart, fracPart string
	if scale > 0 {
		parts := strings.SplitN(s, ".", 2)
		intPart = parts[0]
		if len(parts) > 1 {
			fracPart = parts[1]
		} else {
			fracPart = strings.Repeat("0", scale)
		}
		// pad frac
		if len(fracPart) < scale {
			fracPart = fracPart + strings.Repeat("0", scale-len(fracPart))
		}
	} else {
		intPart = s
		if intPart == "" {
			intPart = "0"
		}
	}
	// Handle overflow: high-order digits dropped
	// Number of digit positions in integer part of picture = count of 9/Z
	digitCapacity := 0
	for _, ch := range intPic {
		if ch == '9' || ch == 'Z' {
			digitCapacity++
		}
	}
	if len(intPart) > digitCapacity {
		intPart = intPart[len(intPart)-digitCapacity:]
	}
	// Now build integer field of width len(intPic) with commas/digits
	// We need to map digit positions to characters
	// Create array for int section
	intWidth := len(intPic)
	intResult := make([]byte, intWidth)
	// Pad intPart with leading zeros to digitCapacity
	paddedInt := strings.Repeat("0", digitCapacity-len(intPart)) + intPart
	// Fill from rightmost
	digitIdx := len(paddedInt) - 1
	for i := intWidth - 1; i >= 0; i-- {
		pc := intPic[i]
		if pc == ',' {
			// comma placeholder: will be comma unless suppressed
			// For now put comma, later may replace with space if in suppressed zone
			intResult[i] = ','
		} else if pc == '9' || pc == 'Z' {
			// digit
			if digitIdx >= 0 {
				intResult[i] = paddedInt[digitIdx]
				digitIdx--
			} else {
				intResult[i] = '0'
			}
		} else {
			intResult[i] = byte(pc)
		}
	}
	// Apply Z suppression: leading zeros become spaces, commas in suppressed zone become spaces
	// Find first non-zero digit in paddedInt terms, but we need to know suppression zone
	// Z suppression goes from left until first non-zero digit (in digit terms) is encountered
	// All Z positions before that become spaces, commas between them also spaces.
	// 9 positions always show digit (even if zero) but if they are leading beyond suppression? In pics with ZZ9, the 9 ensures at least one digit.
	// Algorithm: iterate intResult left to right, keep flag suppressing = true until we encounter a digit '1'-'9' in a Z/9 position
	// Actually '0' in Z position is suppressed.
	suppressing := true
	for i := 0; i < intWidth; i++ {
		pc := intPic[i]
		if pc == 'Z' || pc == ',' {
			if suppressing {
				if pc == ',' {
					intResult[i] = ' '
				} else { // Z
					if intResult[i] == '0' {
						intResult[i] = ' '
					} else {
						// non-zero digit ends suppression
						suppressing = false
					}
				}
			} else {
				// suppression ended, commas stay commas, digits stay
			}
		} else if pc == '9' {
			// 9 never suppressed; suppression ends here
			suppressing = false
		}
		// if we are still suppressing and we just passed a non-space digit (should have ended), check: the digit '0' case already handled, non-zero ended.
		// But if digit is '0' in Z and we suppressed, we remain suppressing.
		// If we encounter a digit that is space due to suppression, continue.
		// Need to detect if after processing a Z that held '0'->space we remain suppressing; correctly.
	}
	// Build final string
	var out string
	if scale > 0 {
		out = string(intResult) + "." + fracPart
	} else {
		out = string(intResult)
	}
	// Ensure width == len(pic)
	if len(out) != width {
		// pad or trim (should not happen)
		if len(out) < width {
			out = strings.Repeat(" ", width-len(out)) + out
		} else {
			out = out[len(out)-width:]
		}
	}
	if negative {
		// COBOL would handle sign, but not needed in this program (all positive)
		// Place minus at last suppressed position or overwrites?
		// Not required
	}
	return out
}

func formatNumericUnedited(v int64, digits int) string {
	s := fmt.Sprintf("%d", v)
	if len(s) > digits {
		s = s[len(s)-digits:]
	} else if len(s) < digits {
		s = strings.Repeat("0", digits-len(s)) + s
	}
	return s
}

func padRight(s string, n int) string {
	if len(s) > n {
		return s[:n]
	}
	if len(s) < n {
		return s + strings.Repeat(" ", n-len(s))
	}
	return s
}

func main() {
	var err error
	orderFile, err = os.Open("input.dat")
	if err != nil {
		// if file not exists, treat as empty
		if os.IsNotExist(err) {
			orderFile = nil
			orderReader = bufio.NewScanner(strings.NewReader(""))
		} else {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
	}
	if orderFile != nil {
		orderReader = bufio.NewScanner(orderFile)
	}

	WsEofFlag = "N"
	inputDone = false

	MAIN_PARA()

	if orderFile != nil {
		orderFile.Close()
	}
}

func MAIN_PARA() {
	// OPEN INPUT ORDER-FILE
	READ_PARA()
	for !inputDone {
		PROCESS_PARA()
	}
	// CLOSE
	SUMMARY_PARA()
}

func READ_PARA() {
	if orderReader == nil || !orderReader.Scan() {
		// check error
		WsEofFlag = "Y"
		inputDone = true
		return
	}
	line := orderReader.Text()
	// pad with spaces to 15
	if len(line) < 15 {
		line = line + strings.Repeat(" ", 15-len(line))
	}
	if len(line) > 15 {
		line = line[:15]
	}
	OrderRecVar.OrId = line[0:5]
	OrderRecVar.OrStat = line[5:6]
	// OrQty 9(3)
	qtyStr := line[6:9]
	qtyStr = strings.TrimSpace(qtyStr)
	if qtyStr == "" {
		OrderRecVar.OrQty = 0
	} else {
		var q int64
		fmt.Sscan(qtyStr, &q)
		OrderRecVar.OrQty = q
	}
	priceStr := line[9:15]
	priceStr = strings.TrimSpace(priceStr)
	if priceStr == "" {
		OrderRecVar.OrPrice = decimal.NewFromInt(0)
	} else {
		// digits only, implied 2 decimals
		var n int64
		fmt.Sscan(priceStr, &n)
		OrderRecVar.OrPrice = decimal.New(n, -2)
	}
}

func PROCESS_PARA() {
	WsTotal = decimal.NewFromInt(0)
	// EVALUATE TRUE
	if OrderRecVar.OrQty == 0 {
		WsBadQty++
		// DISPLAY OR-ID " BAD QTY"
		fmt.Println(OrderRecVar.OrId + " BAD QTY")
	} else if OrderRecVar.OrStat == "N" {
		// COMPUTE WS-TOTAL = OR-QTY * OR-PRICE
		price := OrderRecVar.OrPrice
		qtyDec := decimal.NewFromInt(OrderRecVar.OrQty)
		WsTotal = qtyDec.Mul(price)
		// truncate to 2 decimals (scale of WS-TOTAL)
		WsTotal = WsTotal.Truncate(2)
		// drop high-order if overflow? PIC 9(8)V99 can hold up to 8 int digits; assume within
		WsNewCount++
		SHOW_PARA()
	} else if OrderRecVar.OrStat == "S" {
		qtyDec := decimal.NewFromInt(OrderRecVar.OrQty)
		WsTotal = qtyDec.Mul(OrderRecVar.OrPrice).Mul(decimal.NewFromFloat(1.05))
		// ROUNDED to scale 2
		WsTotal = WsTotal.Round(2)
		WsShipCount++
		SHOW_PARA()
	} else if OrderRecVar.OrStat == "C" {
		WsCancelCount++
		SHOW_PARA()
	} else {
		WsInvalid++
		fmt.Println(OrderRecVar.OrId + " BAD STATUS " + OrderRecVar.OrStat)
	}
	WsGrand = WsGrand.Add(WsTotal)
	READ_PARA()
}

func SHOW_PARA() {
	// MOVE OR-QTY TO WS-QTY-ED etc.
	WsQtyEd = formatEdited(decimal.NewFromInt(OrderRecVar.OrQty), "ZZ9")
	WsPriceEd = formatEdited(OrderRecVar.OrPrice, "Z,ZZ9.99")
	WsTotalEd = formatEdited(WsTotal, "ZZ,ZZZ,ZZ9.99")
	fmt.Println(OrderRecVar.OrId + " " + OrderRecVar.OrStat + " " + WsQtyEd + " " + WsPriceEd + " " + WsTotalEd)
}

func SUMMARY_PARA() {
	WsGrandEd = formatEdited(WsGrand, "Z,ZZZ,ZZZ,ZZ9.99")
	// DISPLAY "NEW: " WS-NEW-COUNT " SHIPPED: " WS-SHIP-COUNT " CANCELLED: " WS-CANCEL-COUNT
	fmt.Println("NEW: " + formatNumericUnedited(WsNewCount, 2) + " SHIPPED: " + formatNumericUnedited(WsShipCount, 2) + " CANCELLED: " + formatNumericUnedited(WsCancelCount, 2))
	fmt.Println("INVALID: " + formatNumericUnedited(WsInvalid, 2) + " BAD QTY: " + formatNumericUnedited(WsBadQty, 2))
	fmt.Println("GRAND TOTAL: " + WsGrandEd)
}

